{
  "decision": "add_family",
  "rationale": "Round 1 mapped the front well on both objectives: luts_plus_ffs spans 903..2761 against HV ref 3000 and accuracy_bits spans 10.9..16.4 against HV ref 10, so the pipelined/pipelined_m front already covers the reference box. The one structural gap is that the `iterative` family (1 micro-rotation/cycle, shared datapath) has never been evaluated, and it is the family most likely to push luts_plus_ffs below the current cheapest design (pipelined_m @ 903). The throughput constraint is only >=2 MSPS and the best feasible throughput seen is 282 MSPS, so a low-throughput shared-datapath design has ample headroom on that constraint; the binding risk is the sys_p99_latency_us<=0.4 bound (best seen 0.066, so there is margin, but L1 is optimistic and L2 may drop the cheapest burst-queuing designs). unrolled_k produced 0 feasible designs in 30 evals, so it is not worth more budget. Bringing in `iterative` is the highest-value move for extending the area end of the front.",
  "next_plan": {
    "families": [
      {
        "family": "iterative",
        "ranges": [
          {"param": "data_width", "low": 14, "high": 22, "choices": null},
          {"param": "n_iter", "low": 12, "high": 20, "choices": null},
          {"param": "angle_guard", "low": -1, "high": 3, "choices": null},
          {"param": "frac_guard", "low": 0, "high": 2, "choices": null},
          {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
        ]
     , "budget_share": 0.6
      ,
      "why": "shared datapath should give the lowest LUT+FF; keep data_width/n_iter near the accuracy-feasible region (front uses 16..20 / 12..20) so max_abs_err<=2^-10 is met while exploring cheaper area points"
      }
    ],
    "rationale": "Focus the round on the unexplored iterative family around the accuracy-feasible region seen on the front, to try to extend luts_plus_ffs below 903; keep a share for pipelined_m refinement near its 903..1426 corner."
  }
}
